@js:
var tab;
type = source.get('type');
var processedType = String(type).replace(/^\s+|\s+$/g, '').toLowerCase();
if (!type || type == "undefined") {
    tab = 3;
} else {
    switch(processedType) {
        case 'novel':
            tab = 3;
            break;
        case 'novelaudio':
            tab = 3;
            break;
        case 'audio':
            tab = 2;
            break;
        case 'comic':
            tab = 8;
            break;
        case 'video':
            tab = 11;
            break;
        default:
            tab = 3;
            break;
    }
}
if (String(key).startsWith("m:") || String(key).startsWith("m：")) {
    tab = 8
    source.put('type','comic')
    key = key.slice(2)
}
if (String(key).startsWith("t:") || String(key).startsWith("t：")) {
    tab = 2
    source.put('type','audio')
    key = key.slice(2)
}
if (String(key).startsWith("d:") || String(key).startsWith("d：")) {
    tab = 11
    source.put('type','video')
    key = key.slice(2)
}
if (key.length == 19 && !Number.isNaN(parseInt(key))) {
    result = source.key + '/detail?bookid=' + key
} else {
    result = source.key + '/search?query=' + encodeURI(java.put("key", key)) + '&offset=' + ((java.put("page", page) - 1) * 10) + '&tab_type=' + tab
}

