const tomatoSources = ["番茄小说", "番茄听书", "番茄畅听"];

if (tomatoSources.includes("{{$.source}}")) {
    try {
        let fqurl = JSON.parse(java.base64Decode(baseUrl.split(",")[1]));
        let finalUrl = java.base64Decode(fqurl.url);
        let response = java.ajax(finalUrl);
        let responseData = JSON.parse(response);

        if (responseData.data && responseData.data.length > 0) {
            let bookData = responseData.data[0];
            let output = `&nbsp;&nbsp;
✨ 源站：{{$.source}}{{"\n"+"​"}}
📕 源名：${bookData.original_book_name}`;

            if (bookData.book_flight_alias_name) {
                output += `\n📖 别名：${bookData.book_flight_alias_name}`;
            }
            output += `\n✏️ 开坑：${bookData.create_time.split('T')[0]} 
🧭 更新：${java.timeFormat(parseInt(bookData.last_chapter_update_time)*1000)}&lrm;
👤 主角：${bookData.roles.replace(/[\[\]"]/g,'')}
🏷️ 标签：${bookData.tags}
👁️ 在线：${bookData.read_count}人在读
🔗 书籍状态：${bookData.book_search_visible == 'true' ? '正常' : (bookData.tomato_book_status == '3' ? '下架' : '小黑屋')}`;

            if (["番茄听书", "番茄畅听"].includes("{{$.source}}")) {
                try {
                    let tones = "\n===================\n🎧AI音色编号信息: ";
            let info = JSON.parse(java.ajax(`https://reading.snssdk.com/reading/bookapi/audio/toneinfo/?book_id=${bookData.book_id}&aid=1967`));
                    for (let i of (info.data.tts_tones ? info.data.tts_tones : [])) {
                        tones += `\n${i.id} - ${i.title}${i.description ? "(" + i.description + ")" : ""}`;
                    }
                    output += tones;
                } catch (e) {
                }
            }
            output += `{{"\n"+"​"}}
📜 简介：${bookData.abstract}{{"\n"+"​"}}
📍 ${bookData.copyright_info.split('，')[0]}。
​`;
            result = output;
        }
    } catch (e) {
    }
}
result;
</js>

